package com.scriptles.cabinet.profile.controller;
import com.scriptles.cabinet.common.api.PageResponse; import com.scriptles.cabinet.profile.dto.ProfileSearchResponse; import com.scriptles.cabinet.profile.entity.Profile; import com.scriptles.cabinet.profile.repository.ProfileFollowRepository; import com.scriptles.cabinet.profile.repository.ProfileRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.PageRequest; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import com.scriptles.cabinet.security.AuthenticatedUser; import java.util.*;
@RestController @RequestMapping("/v1/profiles") @RequiredArgsConstructor public class ProfileConnectionController { private final ProfileRepository profiles; private final ProfileFollowRepository follows;
 @GetMapping("/{handle}/followers") public PageResponse<ProfileSearchResponse> followers(@PathVariable String handle,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){Profile p=profiles.findByHandleIgnoreCase(handle).orElseThrow();return PageResponse.from(follows.followers(p.getId(),PageRequest.of(page,size)).map(this::to));}
 @GetMapping("/{handle}/following") public PageResponse<ProfileSearchResponse> following(@PathVariable String handle,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){Profile p=profiles.findByHandleIgnoreCase(handle).orElseThrow();return PageResponse.from(follows.following(p.getId(),PageRequest.of(page,size)).map(this::to));}
 private ProfileSearchResponse to(Profile p){return new ProfileSearchResponse(p.getId(),p.getType(),p.getHandle(),p.getDisplayName(),p.getAvatarUrl(),p.isVerified(),null);} }
